// Generated by fluxora generate (Rebuild). Change orchestrator/templates, not this file.
// One form that mirrors ClaimScreen (fields come from ./fields, rendered from app.pa.yaml).
// All rule logic runs in the migrated API; this page only collects inputs and shows the result.
import { useState, type FormEvent } from "react";
import { fields, screenTitle, submitLabel, type Field } from "./fields";

type Values = Record<string, string | boolean>;

interface EvaluationResult {
  errors: string[];
  messages: string[];
  excess: number | null;
  payable: number | null;
  lateReport: boolean | null;
  status: string | null;
  firedRules: string[];
}

const initialValues: Values = Object.fromEntries(
  fields.map((f) => [f.name, f.kind === "checkbox" ? false : ""]),
);

function toRequest(values: Values): Record<string, unknown> {
  const body: Record<string, unknown> = {};
  for (const f of fields) {
    const value = values[f.name];
    if (f.kind === "checkbox") body[f.name] = Boolean(value);
    else if (f.kind === "number") body[f.name] = value === "" ? null : Number(value);
    else body[f.name] = value === "" ? null : value;
  }
  return body;
}

const money = (value: number | null) =>
  value === null ? "-" : value.toLocaleString("en-GB", { style: "currency", currency: "GBP" });

function Input({ field, value, onChange }: { field: Field; value: string | boolean; onChange: (v: string | boolean) => void }) {
  const id = `f-${field.name}`;
  if (field.kind === "checkbox") {
    return (
      <label className="check" htmlFor={id}>
        <input id={id} type="checkbox" checked={Boolean(value)} onChange={(e) => onChange(e.target.checked)} />
        {field.label}
      </label>
    );
  }
  const control =
    field.kind === "select" ? (
      <select id={id} value={String(value)} onChange={(e) => onChange(e.target.value)}>
        <option value="">(choose)</option>
        {field.options?.map((o) => (
          <option key={o} value={o}>
            {o}
          </option>
        ))}
      </select>
    ) : (
      <input
        id={id}
        type={field.kind}
        step={field.kind === "number" ? "0.01" : undefined}
        placeholder={field.placeholder}
        value={String(value)}
        onChange={(e) => onChange(e.target.value)}
      />
    );
  return (
    <div className="field">
      <label htmlFor={id}>{field.label}</label>
      {control}
    </div>
  );
}

export default function App() {
  const [values, setValues] = useState<Values>(initialValues);
  const [result, setResult] = useState<EvaluationResult | null>(null);
  const [problem, setProblem] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  async function submit(event: FormEvent) {
    event.preventDefault();
    setBusy(true);
    setProblem(null);
    try {
      const response = await fetch("/claims/evaluate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(toRequest(values)),
      });
      if (!response.ok) {
        setResult(null);
        setProblem(`The API rejected the request (HTTP ${response.status}). Check that every date is filled in.`);
        return;
      }
      setResult((await response.json()) as EvaluationResult);
    } catch {
      setResult(null);
      setProblem("Could not reach the API. Start it with: dotnet run --project generated/api");
    } finally {
      setBusy(false);
    }
  }

  return (
    <main>
      <h1>{screenTitle}</h1>
      <form onSubmit={submit}>
        {fields.map((f) => (
          <Input key={f.name} field={f} value={values[f.name]} onChange={(v) => setValues({ ...values, [f.name]: v })} />
        ))}
        <button type="submit" disabled={busy}>
          {busy ? "Submitting..." : submitLabel}
        </button>
      </form>

      {problem && <p className="problem">{problem}</p>}

      {result && (
        <section className="result" aria-live="polite">
          <h2>Result</h2>
          {result.errors.length > 0 && (
            <ul className="errors">
              {result.errors.map((ruleId, i) => (
                <li key={ruleId}>
                  {result.messages[i]} <span className="rule">{ruleId}</span>
                </li>
              ))}
            </ul>
          )}
          <dl>
            <dt>Status</dt>
            <dd>{result.status ?? "-"}</dd>
            <dt>Excess</dt>
            <dd>{money(result.excess)}</dd>
            <dt>Payable</dt>
            <dd>{money(result.payable)}</dd>
            <dt>Late report</dt>
            <dd>{result.lateReport === null ? "-" : result.lateReport ? "Yes" : "No"}</dd>
            <dt>Rules that decided this</dt>
            <dd>{result.firedRules.join(", ") || "-"}</dd>
          </dl>
        </section>
      )}
    </main>
  );
}
